import { createSlice } from "@reduxjs/toolkit";
const initialState = {
    isOpen: false,
    type: '',
    props: {},
};
const modalSlice = createSlice({
    name: "modal",
    initialState,
    reducers: {
        openModal: (state, action) => {
            const { type, props } = action.payload;
            state.type = type;
            state.props = props;
            state.isOpen = true;
        },
        closeModal: (state) => {
            state.isOpen = false;
            state.type = '';
            state.props = {};
        }
    }
});
export const { openModal, closeModal } = modalSlice.actions;
export default modalSlice;
